-- 2 Revenue_Share 
-- What is the total revenue contribution and percentage of total revenue generated by each segment

SELECT
    Country AS segment,
    ROUND(SUM(Quantity * UnitPrice), 2) AS total_revenue,
    ROUND(100.0 * SUM(Quantity * UnitPrice)
          / SUM(SUM(Quantity * UnitPrice)) OVER (), 2) percentage
FROM data
WHERE Quantity > 0
  AND UnitPrice > 0
GROUP BY Country
ORDER BY total_revenue DESC;

-- The percentage and total revenue that contributed across all the segment was generated from
-- highest to the lowest. That United Kingdom leading with 82.12% and total
-- revenue of 1121137.12 , follow by Germany with 2.78% and total revenue 37933.06.
-- The least one is  Austria with 0.06%  and total revenue of 795.56
